sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) {
    stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance — refusing to run against a live tenant');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var push = {
    sam_request_id: 'ATF-SAM-0001',
    access_item: 'ATF-Test-Role',
    requested_for: 'atf-correlation-0001',
    approval_authority: 'app-owner',
    risk_tier: '2',
    justification: 'ATF happy-path fixture'
  };
  outputs.sam_request_id = push.sam_request_id;
  outputs.requested_for = push.requested_for;
  var v = sam.validateInboundPush(push);
  v.ok ? stepResult.setSuccess()
       : stepResult.setFailed('validateInboundPush should accept a fully-populated push: ' + v.reason);
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var pulled = sam.fetchIdentityRequest('ATF-SAM-0001');
  if (!pulled.ok) { stepResult.setFailed('fetchIdentityRequest should return a canned approval in test_mode: ' + pulled.reason); return; }
  var st = ('' + (pulled.data.executionStatus || pulled.data.status || '')).toLowerCase();
  if (st !== 'approved' && st !== 'completed') { stepResult.setFailed('canned status should read approved/completed, got: ' + st); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var lineage = sam.recordLineage(null, 'ATF-SAM-0001', 'atf-correlation-0001', {
    verified_by: 'pull-verify',
    verified_at: new GlideDateTime().getValue(),
    verified_authority: 'app-owner',
    verified_status: 'approved',
    verified_item: 'ATF-Test-Role'
  });
  if (!lineage.ok) { stepResult.setFailed('recordLineage should succeed with a valid sam_request_id: ' + JSON.stringify(lineage)); return; }

  var req = new GlideRecord('sc_request');
  req.initialize();
  req.setValue('short_description', 'ATF SAM happy-path fixture — safe to ignore');
  var ritmSysId = req.insert();
  if (!ritmSysId) { stepResult.setFailed('fixture RITM insert failed'); return; }
  var ritmNumber = req.getValue('number');
  outputs.ritm_number = ritmNumber;

  var bound = sam.attachRitmToLineage(lineage.sys_id, ritmNumber, '' + ritmSysId);
  bound.ok ? stepResult.setSuccess()
           : stepResult.setFailed('attachRitmToLineage should bind the lineage row to the RITM: ' + JSON.stringify(bound));
})(outputs, steps, stepResult);
